constexpr int fibonacci(int n) {
    if (n == 0) return 0;
    if (n == 1) return 1;
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main() {
    constexpr int x = fibonacci(10); // computed at compile time -> 55
    int arr[x];                       // valid: x is a compile-time constant
    return 0;
}

#include <vector>
#include <map>
using namespace std;

int main() {
    vector<int> v = {1, 2, 3, 4, 5};

    // By value (copy)
    for (int x : v) printf("%d ", x);

    // By reference (modify in place)
    for (int& x : v) x *= 2;

    // By const reference (read-only, no copy)
    for (const int& x : v) printf("%d ", x);

    map<string, int> m = {{"a", 1}, {"b", 2}};
    for (auto& [key, val] : m) // structured binding
        printf("%s=%d ", key.c_str(), val);
    return 0;
}

