using namespace std;

struct Point { int x, y, z; };

int main() {
    // Binding a struct
    Point p = {1, 2, 3};
    auto [px, py, pz] = p;

    // Binding a pair
    pair<string, int> kv = {"score", 100};
    auto [key, val] = kv;

    // Most useful: iterating a map
    map<string, int> grades = {{"Alice", 9}, {"Bob", 10}};
    for (auto& [name, grade] : grades)
        printf("%s: %d\n", name.c_str(), grade);
    return 0;
}

// CRTP base: method chaining example
template<typename T>
class Printable {
public:
    T& print() {
        printf("%s\n", static_cast<T*>(this)->toString());
        return static_cast<T&>(*this); // return derived type
    }
};

class MyClass : public Printable<MyClass> {
public:
    const char* toString() const { return "MyClass instance"; }
    MyClass& doSomething() { printf("doing something\n"); return *this; }
};

int main() {
    MyClass obj;
    obj.print().doSomething(); // method chaining works!
    return 0;
}
